{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { createReadStream } from 'fs'
import { parseURI, normalizeURI, resolveURI, formatURI } from './uri.js'

const mode = process.argv[2]

// Validate mode
if (!mode || !['normalize', 'resolve'].includes(mode)) {
  process.stderr.write('error: usage: cli.js normalize|resolve\n')
  process.exit(2)
}

// Read stdin
let input = ''
process.stdin.setEncoding('utf8')

process.stdin.on('data', (chunk) => {
  input += chunk
})

process.stdin.on('end', () => {
  try {
    const lines = input.split('\n')
    // Remove empty tail from trailing newline
    if (lines.length > 0 && lines[lines.length - 1] === '') {
      lines.pop()
    }

    for (let lineNum = 0; lineNum < lines.length; lineNum++) {
      const line = lines[lineNum]
      const recordNum = lineNum + 1

      if (mode === 'normalize') {
        const normalized = normalizeURI(line)
        console.log(formatURI(normalized))
      } else if (mode === 'resolve') {
        // Split on first space only
        const spaceIdx = line.indexOf(' ')
        if (spaceIdx === -1) {
          process.stderr.write(`error: line ${recordNum}: expected a base and a reference\n`)
          process.exit(2)
        }

        const baseStr = line.substring(0, spaceIdx)
        const refStr = line.substring(spaceIdx + 1)

        const baseParsed = parseURI(baseStr)
        if (!baseParsed.scheme) {
          process.stderr.write(`error: line ${recordNum}: the base has no scheme\n`)
          process.exit(2)
        }

        const resolved = resolveURI(baseParsed, refStr)
        const normalized = normalizeURI(formatURI(resolved))
        console.log(formatURI(normalized))
      }
    }

    process.exit(0)
  } catch (error) {
    process.stderr.write(`error: ${error.message}\n`)
    process.exit(2)
  }
})
"}

