{"file_path":"src/uri.js","content":"/**
 * URI parsing, normalization, and resolution according to RFC 3986
 */

/**
 * Parse a URI reference into components
 * @param {string} uri - The URI reference string
 * @returns {object} - Object with scheme, authority, path, query, fragment properties
 */
export function parseURI(uri) {
  let scheme = null
  let authority = null
  let path = ''
  let query = null
  let fragment = null

  // Step 1: Extract fragment (from # to end)
  let remaining = uri
  const fragmentIdx = remaining.indexOf('#')
  if (fragmentIdx !== -1) {
    fragment = remaining.substring(fragmentIdx + 1)
    remaining = remaining.substring(0, fragmentIdx)
  }

  // Step 2: Extract query (from ? to end)
  const queryIdx = remaining.indexOf('?')
  if (queryIdx !== -1) {
    query = remaining.substring(queryIdx + 1)
    remaining = remaining.substring(0, queryIdx)
  }

  // Step 3: Extract scheme (up to first :, but only if no / before it)
  const colonIdx = remaining.indexOf(':')
  if (colonIdx !== -1) {
    const beforeColon = remaining.substring(0, colonIdx)
    if (!beforeColon.includes('/')) {
      scheme = beforeColon
      remaining = remaining.substring(colonIdx + 1)
    }
  }

  // Step 4: Extract authority (from // to next / or end)
  if (remaining.startsWith('//')) {
    const afterDoubleSlash = remaining.substring(2)
    const slashIdx = afterDoubleSlash.indexOf('/')
    if (slashIdx !== -1) {
      authority = afterDoubleSlash.substring(0, slashIdx)
      path = afterDoubleSlash.substring(slashIdx)
    } else {
      authority = afterDoubleSlash
      path = ''
    }
  } else {
    path = remaining
  }

  return { scheme, authority, path, query, fragment }
}

/**
 * Format a parsed URI back to string
 * @param {object} uri - Parsed URI object
 * @returns {string} - Formatted URI string
 */
export function formatURI(uri) {
  let result = ''

  if (uri.scheme) {
    result += uri.scheme + ':'
  }

  if (uri.authority !== null) {
    result += '//' + uri.authority
  }

  result += uri.path

  if (uri.query !== null) {
    result += '?' + uri.query
  }

  if (uri.fragment !== null) {
    result += '#' + uri.fragment
  }

  return result
}

/**
 * Normalize percent-encoding in a component
 * @param {string} component - The component to normalize
 * @returns {string} - Normalized component
 * @throws {Error} - If percent-encoding is truncated or invalid
 */
function normalizePercentEncoding(component) {
  let result = ''
  for (let i = 0; i < component.length; i++) {
    if (component[i] === '%') {
      if (i + 2 >= component.length) {
        throw new Error('truncated percent-encoding')
      }
      const hex = component.substring(i + 1, i + 3)
      if (!/^[0-9A-Fa-f]{2}$/.test(hex)) {
        throw new Error('truncated percent-encoding')
      }
      const code = parseInt(hex, 16)
      const char = String.fromCharCode(code)
      // Check if unreserved: A-Z a-z 0-9 - . _ ~
      if (/^[A-Za-z0-9\-._~]$/.test(char)) {
        result += char
      } else {
        result += '%' + hex.toUpperCase()
      }
      i += 2
    } else {
      result += component[i]
    }
  }
  return result
}

/**
 * Parse authority into userinfo, host, and port
 * @param {string|null} authority - The authority string
 * @returns {object} - Object with userinfo, host, port properties
 */
function parseAuthority(authority) {
  if (!authority) return { userinfo: null, host: null, port: null }

  // Find last @
  const lastAtIdx = authority.lastIndexOf('@')
  let userinfo = null
  let hostPort = authority

  if (lastAtIdx !== -1) {
    userinfo = authority.substring(0, lastAtIdx)
    hostPort = authority.substring(lastAtIdx + 1)
  }

  // Parse host:port, handling IPv6
  let host = hostPort
  let port = null

  const lastBracketIdx = hostPort.lastIndexOf(']')
  let colonIdx = -1

  if (lastBracketIdx !== -1) {
    // IPv6 address, look for : after the ]
    colonIdx = hostPort.indexOf(':', lastBracketIdx)
  } else {
    // No IPv6, look for first :
    colonIdx = hostPort.indexOf(':')
  }

  if (colonIdx !== -1) {
    host = hostPort.substring(0, colonIdx)
    port = hostPort.substring(colonIdx + 1)
  }

  return { userinfo, host, port }
}

/**
 * Format authority from userinfo, host, and port
 * @param {string|null} userinfo - The userinfo
 * @param {string} host - The host
 * @param {string|null} port - The port
 * @returns {string} - Formatted authority
 */
function formatAuthority(userinfo, host, port) {
  let result = ''
  if (userinfo !== null) {
    result += userinfo + '@'
  }
  result += host
  if (port !== null) {
    result += ':' + port
  }
  return result
}

/**
 * Get the default port for a scheme
 * @param {string|null} scheme - The scheme (lowercased)
 * @returns {string|null} - The default port or null
 */
function getDefaultPort(scheme) {
  const defaults = {
    'http': '80',
    'https': '443',
    'ws': '80',
    'wss': '443',
    'ftp': '21'
  }
  return defaults[scheme] || null
}

/**
 * Remove dot segments from a path
 * @param {string} path - The path
 * @returns {string} - The path with dot segments removed
 */
function removeDotSegments(path) {
  const inputBuffer = path
  const outputBuffer = []

  let i = 0
  while (i < inputBuffer.length) {
    // A: If the input buffer begins with a prefix of "../" or "./"
    if (inputBuffer.substr(i, 3) === '../') {
      i += 3
    } else if (inputBuffer.substr(i, 2) === './') {
      i += 2
    }
    // B: If the input buffer begins with a prefix of "/./"
    else if (inputBuffer.substr(i, 3) === '/./') {
      i += 2
    } else if (inputBuffer.substr(i, 2) === '/.') {
      // or consists only of "/."
      if (inputBuffer.length === i + 2) {
        inputBuffer = inputBuffer.substring(0, i) + '/'
        continue
      } else {
        i += 2
      }
    }
    // C: If the input buffer begins with a prefix of "/../"
    else if (inputBuffer.substr(i, 4) === '/../') {
      i += 3
      if (outputBuffer.length > 0) {
        outputBuffer.pop()
      }
    } else if (inputBuffer.substr(i, 3) === '/..') {
      // or consists only of "/.."
      if (inputBuffer.length === i + 3) {
        inputBuffer = inputBuffer.substring(0, i) + '/'
        continue
      } else {
        i += 3
        if (outputBuffer.length > 0) {
          outputBuffer.pop()
        }
      }
    }
    // D: If the input buffer consists only of "." or ".."
    else if ((inputBuffer === '.' || inputBuffer === '..') && i === 0) {
      i = inputBuffer.length
    }
    // E: Move the first path segment in the input buffer to the end of the output buffer
    else {
      let j = i
      if (inputBuffer[i] === '/') {
        j++
      }
      while (j < inputBuffer.length && inputBuffer[j] !== '/') {
        j++
      }
      outputBuffer.push(inputBuffer.substring(i, j))
      i = j
    }
  }

  return outputBuffer.join('')
}

/**
 * Normalize a parsed URI
 * @param {object|string} uri - Parsed URI object or string
 * @returns {object} - Normalized URI object
 * @throws {Error} - If percent-encoding is truncated
 */
export function normalizeURI(uri) {
  // Handle string input
  if (typeof uri === 'string') {
    uri = parseURI(uri)
  }

  const normalized = {}

  // Step 1: Lowercase scheme (ASCII only)
  normalized.scheme = uri.scheme ? uri.scheme.toLowerCase() : null

  // Parse authority components for normalization
  const { userinfo, host, port } = parseAuthority(uri.authority)

  // Step 2: Normalize percent-encodings in components (in order: userinfo, host, path, query, fragment)
  let normalizedUserinfo = null
  let normalizedHost = null
  let normalizedPort = null

  if (userinfo !== null) {
    try {
      normalizedUserinfo = normalizePercentEncoding(userinfo)
    } catch {
      throw new Error('line N: userinfo has a truncated percent-encoding'.replace('line N', ''))
    }
  }

  if (host !== null) {
    try {
      normalizedHost = normalizePercentEncoding(host).toLowerCase()
    } catch {
      throw new Error('line N: host has a truncated percent-encoding'.replace('line N', ''))
    }
  }

  // Step 3: Handle port - drop if default or empty
  if (port !== null && port !== '') {
    const defaultPort = getDefaultPort(normalized.scheme)
    if (defaultPort && port === defaultPort) {
      normalizedPort = null
    } else {
      normalizedPort = port
    }
  } else {
    normalizedPort = null
  }

  // Reconstruct authority
  if (uri.authority !== null) {
    normalized.authority = formatAuthority(normalizedUserinfo, normalizedHost, normalizedPort)
  } else {
    normalized.authority = null
  }

  // Step 4: Normalize path
  let normalizedPath = uri.path
  try {
    normalizedPath = normalizePercentEncoding(normalizedPath)
  } catch {
    throw new Error('line N: path has a truncated percent-encoding'.replace('line N', ''))
  }
  normalizedPath = removeDotSegments(normalizedPath)

  // Step 5: Add leading / to path if authority present and path is empty
  if (uri.authority !== null && normalizedPath === '') {
    normalizedPath = '/'
  }

  normalized.path = normalizedPath

  // Normalize query and fragment
  let normalizedQuery = null
  if (uri.query !== null) {
    try {
      normalizedQuery = normalizePercentEncoding(uri.query)
    } catch {
      throw new Error('line N: query has a truncated percent-encoding'.replace('line N', ''))
    }
  }
  normalized.query = normalizedQuery

  let normalizedFragment = null
  if (uri.fragment !== null) {
    try {
      normalizedFragment = normalizePercentEncoding(uri.fragment)
    } catch {
      throw new Error('line N: fragment has a truncated percent-encoding'.replace('line N', ''))
    }
  }
  normalized.fragment = normalizedFragment

  return normalized
}

/**
 * Resolve a reference against a base URI
 * @param {object|string} base - Parsed base URI object or string
 * @param {string} reference - The reference string
 * @returns {object} - Resolved URI object (not normalized)
 */
export function resolveURI(base, reference) {
  // Handle string base
  if (typeof base === 'string') {
    base = parseURI(base)
  }

  const ref = parseURI(reference)
  let target = {}

  // RFC 3986 section 5.2.2 - strict form resolution
  if (ref.scheme !== null) {
    // Reference has a scheme - it's already absolute
    target.scheme = ref.scheme
    target.authority = ref.authority
    target.path = removeDotSegments(ref.path)
    target.query = ref.query
  } else {
    if (ref.authority !== null) {
      // Reference has authority
      target.authority = ref.authority
      target.path = removeDotSegments(ref.path)
      target.query = ref.query
    } else {
      if (ref.path === '') {
        // Reference has empty path
        target.path = base.path
        if (ref.query !== null) {
          target.query = ref.query
        } else {
          target.query = base.query
        }
      } else {
        if (ref.path.startsWith('/')) {
          // Reference has absolute path
          target.path = removeDotSegments(ref.path)
        } else {
          // Reference has relative path - merge with base
          if (base.authority !== null && base.path === '') {
            target.path = '/' + ref.path
          } else {
            const lastSlash = base.path.lastIndexOf('/')
            if (lastSlash !== -1) {
              target.path = base.path.substring(0, lastSlash + 1) + ref.path
            } else {
              target.path = ref.path
            }
          }
          target.path = removeDotSegments(target.path)
        }
        target.query = ref.query
      }
      target.authority = base.authority
    }
    target.scheme = base.scheme
  }

  target.fragment = ref.fragment

  return target
}
