/** Thrown when a component holds a `%` without two hexadecimal digits. */
export class PercentError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

/** Lowercase using ASCII rules only. */
function asciiLower(text) {
  let out = ''
  for (const ch of text) {
    const code = ch.codePointAt(0)
    out += code >= 0x41 && code <= 0x5a ? String.fromCharCode(code + 32) : ch
  }
  return out
}

/**
 * Parse a URI reference into its five generic components. An absent
 * component is null; an empty one is the empty string.
 */
export function parseURI(uri) {
  let scheme = null
  let authority = null
  let path = ''
  let query = null
  let fragment = null

  let rest = uri

  const hash = rest.indexOf('#')
  if (hash !== -1) {
    fragment = rest.slice(hash + 1)
    rest = rest.slice(0, hash)
  }

  const question = rest.indexOf('?')
  if (question !== -1) {
    query = rest.slice(question + 1)
    rest = rest.slice(0, question)
  }

  const colon = rest.indexOf(':')
  if (colon !== -1 && !rest.slice(0, colon).includes('/')) {
    scheme = rest.slice(0, colon)
    rest = rest.slice(colon + 1)
  }

  if (rest.startsWith('//')) {
    const after = rest.slice(2)
    const slash = after.indexOf('/')
    if (slash === -1) {
      authority = after
      path = ''
    } else {
      authority = after.slice(0, slash)
      path = after.slice(slash)
    }
  } else {
    path = rest
  }

  return { scheme, authority, path, query, fragment }
}

/** Serialize the five components back into a URI reference. */
export function formatURI(uri) {
  let out = ''
  if (uri.scheme !== null) out += uri.scheme + ':'
  if (uri.authority !== null) out += '//' + uri.authority
  out += uri.path
  if (uri.query !== null) out += '?' + uri.query
  if (uri.fragment !== null) out += '#' + uri.fragment
  return out
}

/** Split an authority into userinfo, host and port. */
export function parseAuthority(authority) {
