const UNRESERVED = /^[A-Za-z0-9\-._~]$/

/**
 * Uppercase the hexadecimal digits of every `%XX` and decode the triplets
 * that stand for an unreserved character.
 */
function normalizePercent(text, component) {
  let out = ''
  for (let i = 0; i < text.length; i++) {
    const ch = text[i]
    if (ch !== '%') {
      out += ch
      continue
    }
    const hex = text.slice(i + 1, i + 3)
    if (hex.length < 2 || !HEX.test(hex)) throw new PercentError(component)
    const decoded = String.fromCharCode(parseInt(hex, 16))
    out += UNRESERVED.test(decoded) ? decoded : '%' + hex.toUpperCase()
    i += 2
  }
  return out
}

/** Remove dot segments from a path, per RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
