    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let end = input.indexOf('/', input.startsWith('/') ? 1 : 0)
      if (end === -1) end = input.length
      output.push(input.slice(0, end))
      input = input.slice(end)
    }
  }

