 * Resolve a parsed reference against a parsed base, strictly, and return the
 * parsed target (not yet normalized).
 */
export function resolve(base, ref) {
  const target = { scheme: null, authority: null, path: '', query: null, fragment: null }

  if (ref.scheme !== null) {
    target.scheme = ref.scheme
    target.authority = ref.authority
