import { readFileSync } from 'node:fs'
import { parseURI, normalize, resolve, PercentError } from './uri.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const argv = process.argv.slice(2)
if (argv.length !== 1 || (argv[0] !== 'normalize' && argv[0] !== 'resolve')) {
  fail('usage: cli.js normalize|resolve')
