  const record = records[i]
  const n = i + 1

  try {
    if (mode === 'normalize') {
      out.push(normalize(parseURI(record)))
    } else {
      const space = record.indexOf(' ')
      if (space === -1) fail(`line ${n}: expected a base and a reference`)

      const base = parseURI(record.slice(0, space))
      if (base.scheme === null) fail(`line ${n}: the base has no scheme`)

      const ref = parseURI(record.slice(space + 1))
      out.push(normalize(resolve(base, ref)))
    }
  } catch (error) {
    if (error instanceof PercentError) fail(`line ${n}: ${error.message}`)
    throw error
  }
}

